    "content": "36氪获悉，欧菲光8月9日发布关于媒体报道的澄清公告，8月6日前后，个别媒体发布了报道质疑公司实际控制人蔡荣军向其实际控制的新菲光通信技术有限公司、新思考电机股份有限公司进行利益输送。公司与新菲光在业务模式与产品线上完全独立。公司未为新菲光生产或代工该报道所述光模块光学组件、玻璃桥、精密结构件等产品，不存在人为压低公司零部件售价、向新菲光转移利润的行为。新思考由公司董事长蔡荣军及其控制的企业深圳和正收购而来，不存在“早年从欧菲光拆分VCM马达核心业务，欧菲光承担全部研发成本，成熟后高毛利业务归新思考。”的情况。"
