    "title": "俄国防部：拦截285架乌克兰无人机并对乌发动空袭",
    "link": "http://www.news.cn/20260810/d0c990e6baa6445e946406f047edb4db/c.html",
    "pub_date": "2026-08-10 03:58:01",
    "author": "赵冰",
    "description": "新华社莫斯科8月9日电（记者赵冰）俄罗斯国防部9日晚发布通报说，莫斯科时间当天8时至20时，俄防空部队在俄罗斯多个地区拦截并击落285架乌克兰无人机。 通报说，这些无人机是在别尔哥罗德州、库尔斯克州、布良斯克州、图拉州、利佩茨克州、梁赞州、奥廖尔州、卡卢加州以及莫斯科地区等地上空被拦截并击落。 通报还说，俄武装部队空袭了乌克兰境内的热电厂和7个变电站，并用无人机打击乌克兰苏梅州一处天然气田基础设施。",
    "content": "新华社莫斯科8月9日电（记者赵冰）俄罗斯国防部9日晚发布通报说，莫斯科时间当天8时至20时，俄防空部队在俄罗斯多个地区拦截并击落285架乌克兰无人机。 通报说，这些无人机是在别尔哥罗德州、库尔斯克州、布良斯克州、图拉州、利佩茨克州、梁赞州、奥廖尔州、卡卢加州以及莫斯科地区等地上空被拦截并击落。 通报还说，俄武装部队空袭了乌克兰境内的热电厂和7个变电站，并用无人机打击乌克兰苏梅州一处天然气田基础设施。"
