    "description": "新华社开普敦8月9日电（记者王晓梅 王雷）南非警方9日说，南非立法首都开普敦8日晚至9日凌晨接连发生3起枪击事件，共造成11人死亡。 南非西开普省警察局在9日发表的一份声明中说，8日22时50分左右，3名男子在卡耶利查遭枪击身亡。几乎在同一时间，兰加的一起枪击事件造成4名男子和1名女子死亡。9日凌晨，发生在古古莱图的枪击事件造成2名男子和1名女子死亡，另有2人受伤。 声明说，目前尚未逮捕任何嫌疑人。警方已加强事发地区及其他潜在高风险地区…",
    "content": "新华社开普敦8月9日电（记者王晓梅 王雷）南非警方9日说，南非立法首都开普敦8日晚至9日凌晨接连发生3起枪击事件，共造成11人死亡。 南非西开普省警察局在9日发表的一份声明中说，8日22时50分左右，3名男子在卡耶利查遭枪击身亡。几乎在同一时间，兰加的一起枪击事件造成4名男子和1名女子死亡。9日凌晨，发生在古古莱图的枪击事件造成2名男子和1名女子死亡，另有2人受伤。 声明说，目前尚未逮捕任何嫌疑人。警方已加强事发地区及其他潜在高风险地区的警力部署，并呼吁知情人士提供线索。 卡耶利查、兰加、古古莱图均位于开普敦市中心…"
