    "content": "新华社北京8月9日电 题：新华社经济随笔：从空调热销欧洲看中国制造惠及全球 新华社记者戴锦镕 这个夏天，这样一则“清凉”又“火热”的新闻引人关注—— 今年上半年，我国空调、电扇、冰箱等家电合计出口1079.1亿元。从国别来看，今年前5个月，中国对法国、荷兰、比利时等国家的空调出口额同比大幅增长。多款中国空调一经上市就被抢购，在一些国家甚至一度“一机难求”。 空调热销欧洲，一方面是今年欧洲大范围长时间出现高温天气，一方面是全欧家庭空调普及率不高，供需缺口很大。滚滚热浪下，中国制造又一次接住了集中爆发的巨大需求，为欧洲…"
