    "content": "新华社福州8月9日电（记者周义）今年第13号台风“白海豚”来袭，8月8日在福建宁德霞浦县西洋岛，一场争分夺秒的生命救援在海上展开。 交通运输部东海第二救助飞行队机组人员抱着受伤儿童送医。新华社发 “当天上午我们接到求助电话，说岛上一名5岁儿童头部摔伤，存在颅内出血风险，急需出岛送医。”宁德海事局指挥中心一级主任科员陈学论回忆，因台风逼近，海上客渡运船舶已全部停航，海事局立马联系了交通运输部东海救助局。 上午11时许，东海第二救助飞行队“B-7346”机组接到救助指令。“4名机组人员一收到消息，就赶紧拿着东西往机库里…"
