    "content": "中新社广东江门8月9日电 (记者 郭军)8月4日至10日，2026年“少年中国说”华裔新生代使者选拔赛研学营走进侨乡广东江门，开展一场“溯源侨根、对话文明、科创逐梦”之旅。这场由江门市侨务局主办的研学活动，吸引来自德国、荷兰、加拿大、美国、日本等10个国家华文学校的33名华裔师生参与。"
