    "description": "新华社开罗/伊斯坦布尔8月9日电（记者吴宝澍 程睿泽 罗晨）沙特阿拉伯、土耳其和巴基斯坦三国7日在沙特城市麦加签署《麦加共同防务协议》，其中“一国受袭、共同响应”的条款备受关注。 分析人士指出，三国“抱团”的背后，既有近期中东安全形势恶化的现实压力，也反映出地区国家对美国安全承诺信心不足。三国寻求安全防务合作多元化，或将对地区局势产生长远影响，但这一防务协议的实际效果将如何仍有待观察。 三国“抱团” 7日，沙特王储兼首相穆罕默德和到访的…",
    "content": "新华社开罗/伊斯坦布尔8月9日电（记者吴宝澍 程睿泽 罗晨）沙特阿拉伯、土耳其和巴基斯坦三国7日在沙特城市麦加签署《麦加共同防务协议》，其中“一国受袭、共同响应”的条款备受关注。 分析人士指出，三国“抱团”的背后，既有近期中东安全形势恶化的现实压力，也反映出地区国家对美国安全承诺信心不足。三国寻求安全防务合作多元化，或将对地区局势产生长远影响，但这一防务协议的实际效果将如何仍有待观察。 三国“抱团” 7日，沙特王储兼首相穆罕默德和到访的土耳其总统埃尔多安、巴基斯坦总理夏巴兹出席了《麦加共同防务协议》签署仪式。 8月…"
