    "author": "澎湃新闻记者 邹娟 俞凯",
    "description": "2026年8月9日，持续大雨导致上海部分地段积水。澎湃新闻记者当日奔赴多个点位，在上海浦东、长宁等多个现场积水处看到，工作人员封路、垒沙袋、捞杂物……“白海豚”威压下，各条线第一时间抢排水，保障市民台风天出行、商家营业等需求。 世纪大道浦电路路口封路抢排水 当日11时许，浦东新区东方路不少路段积水已漫上人行道，行人几乎都挽起裤脚，积水已至成人小腿肚。来往车辆都涉水而过。澎湃新闻记者乘坐的出租车，水面快到车门处，水波拍打着车身。路边，一辆…",
    "content": "2026年8月9日，持续大雨导致上海部分地段积水。澎湃新闻记者当日奔赴多个点位，在上海浦东、长宁等多个现场积水处看到，工作人员封路、垒沙袋、捞杂物……“白海豚”威压下，各条线第一时间抢排水，保障市民台风天出行、商家营业等需求。 世纪大道浦电路路口封路抢排水 当日11时许，浦东新区东方路不少路段积水已漫上人行道，行人几乎都挽起裤脚，积水已至成人小腿肚。来往车辆都涉水而过。澎湃新闻记者乘坐的出租车，水面快到车门处，水波拍打着车身。路边，一辆蓝色公交车和另一辆私家车已停摆。“水深又堵车，一不小心趴窝了，那就麻烦了。接完你…"
