    "content": "我有一台 2010 年的搭载 Intel Atom N450 和 2G 内存的老笔记本，OpenGL 只支持 2.1，而且一大堆 OpenGL 应用程序会报错显卡 ALU 寄存器不足无法运行。 我试过在它上面玩 minecraft 1.16.5，没有报错 ALU 寄存器不足，在主界面还是流畅 60fps 的，创建存档生成地图要十几分钟，但进游戏以后就非常卡，平均帧时间 1000ms 根本没法玩。即使作为客户端加入服务器平均帧时间也有 600+ms，这样瓶颈都在 CPU，属于完全没救。不过你这个 CPU 肯定比我那个…"
