    "author": "wdv2ly",
    "description": "当初电动牙刷刚发布时，大张旗鼓宣传刷头永久 9 块 9 ，号称牙刷头平价革命。我真信了，买了，结果现在想换刷头，发现九块九商品永远无货，有货的全是均价二三十的。 虽然说也不算贵，但是真挺败好感的，感觉被当傻子玩弄一样。 牙刷本身质量也一般，之前不到一年就充不进电，返修换了个电池，凑合用。 以后不会再考虑这个牌子了。",
    "content": "当初电动牙刷刚发布时，大张旗鼓宣传刷头永久 9 块 9 ，号称牙刷头平价革命。我真信了，买了，结果现在想换刷头，发现九块九商品永远无货，有货的全是均价二三十的。 虽然说也不算贵，但是真挺败好感的，感觉被当傻子玩弄一样。 牙刷本身质量也一般，之前不到一年就充不进电，返修换了个电池，凑合用。 以后不会再考虑这个牌子了。"
