    "description": "新华社耶路撒冷8月9日电（记者陈君清 冯国芮）以色列总理内塔尼亚胡9日说，以色列拒绝美国发起的所谓“和平委员会”提出的加沙和平计划，并称在巴勒斯坦伊斯兰抵抗运动（哈马斯）真正解除武装之前，以军不会撤出加沙地带。 据以色列多家媒体报道，内塔尼亚胡当天在每周例行内阁会议开始时说，“以色列拒绝这份包含15点内容的和平计划”。他说，哈马斯必须解除武装，“是所有武器，包括重型武器和轻型武器，是真正解除武装，而不是虚假的解除武装”。 内塔尼亚胡说，…",
    "content": "新华社耶路撒冷8月9日电（记者陈君清 冯国芮）以色列总理内塔尼亚胡9日说，以色列拒绝美国发起的所谓“和平委员会”提出的加沙和平计划，并称在巴勒斯坦伊斯兰抵抗运动（哈马斯）真正解除武装之前，以军不会撤出加沙地带。 据以色列多家媒体报道，内塔尼亚胡当天在每周例行内阁会议开始时说，“以色列拒绝这份包含15点内容的和平计划”。他说，哈马斯必须解除武装，“是所有武器，包括重型武器和轻型武器，是真正解除武装，而不是虚假的解除武装”。 内塔尼亚胡说，以色列正与美国进行讨论，“他们（美方）有自己的想法，有些我们能接受，有些我们不能…"
