    "description": "8月9日，受今年第13号台风“白海豚”影响，上海迎来明显风雨天气。此次降雨呈现“面强点极端”特点，浦东、黄浦、徐汇、长宁等区域部分路段出现积水。迎战“白海豚”，上海全市抢排，水务部门紧急调度河闸泵联排，防汛、绿化市容、公安、消防等多部门在岗值守，全力确保城市运行安全。 上午，中心城区、浦东新区和闵行先后发布暴雨红色预警信号。记者在徐汇区看到，部分路段出现积水，沿街商铺工作人员及时开展排水处置。 随着雨势减弱，13时上海暴雨预警降级。15…",
    "content": "8月9日，受今年第13号台风“白海豚”影响，上海迎来明显风雨天气。此次降雨呈现“面强点极端”特点，浦东、黄浦、徐汇、长宁等区域部分路段出现积水。迎战“白海豚”，上海全市抢排，水务部门紧急调度河闸泵联排，防汛、绿化市容、公安、消防等多部门在岗值守，全力确保城市运行安全。 上午，中心城区、浦东新区和闵行先后发布暴雨红色预警信号。记者在徐汇区看到，部分路段出现积水，沿街商铺工作人员及时开展排水处置。 随着雨势减弱，13时上海暴雨预警降级。15时，记者看到，中心城区部分路段积水已基本排空，现场工作人员同步清扫路面落叶杂物、…"
