    "title": "丘成桐：以好奇为基础的研究才算是真正的基础研究",
    "link": "https://m.thepaper.cn/detail/33748979",
    "pub_date": "2026-08-09 20:20:30",
    "author": "澎湃新闻记者 程婷",
    "description": "8月9日，在2026国际基础科学大会媒体见面会上，谈到从0到1的原创性研究与应用技术和产业转化相关话题时，数学家、菲尔兹奖首位华人得主丘成桐指出，以好奇为基础的研究才算是真正的基础研究，由好奇心产生的研究很重要。 他以数学为例指出，一些数学研究最初往往看不出来它的重要性，但慢慢接触到工业时才让人恍然大悟，原来这些都是很重要的事情。在以好奇为基础的研究方面，过去中国的攻势不够，现在在向这个方向靠近。他希望中国各个层面都能支持这种由好奇心驱…",
    "content": "8月9日，在2026国际基础科学大会媒体见面会上，谈到从0到1的原创性研究与应用技术和产业转化相关话题时，数学家、菲尔兹奖首位华人得主丘成桐指出，以好奇为基础的研究才算是真正的基础研究，由好奇心产生的研究很重要。 他以数学为例指出，一些数学研究最初往往看不出来它的重要性，但慢慢接触到工业时才让人恍然大悟，原来这些都是很重要的事情。在以好奇为基础的研究方面，过去中国的攻势不够，现在在向这个方向靠近。他希望中国各个层面都能支持这种由好奇心驱动的研究。 在2026国际基础科学大会开幕致辞中，丘成桐也谈到，近年来，中国政府…"
