    "description": "如果给你看一张香蕉的黑白照片，并问：“它原本是什么颜色？”你大概会脱口而出：黄色。毕竟，香蕉实在是再令人熟悉不过了。 但世界上偏偏有这样一小撮人，他们认识香蕉，也认识黄色。可当那张黑白照片摆在面前时，他们却不知道香蕉的颜色。哪怕眼前是一张红色香蕉的图片，他们也未必会觉得哪里不对。 北京大学毕彦超团队和山西医科大学王效春团队仔细研究[1]了这些人的大脑：他们的视觉皮层功能完好，视觉本身并未受损；真正“断线”的，其实是视觉皮层与大脑中语言相…",
    "content": "如果给你看一张香蕉的黑白照片，并问：“它原本是什么颜色？”你大概会脱口而出：黄色。毕竟，香蕉实在是再令人熟悉不过了。 但世界上偏偏有这样一小撮人，他们认识香蕉，也认识黄色。 可当那张黑白照片摆在面前时，他们却不知道香蕉的颜色。哪怕眼前是一张红色香蕉的图片，他们也未必会觉得哪里不对。 北京大学毕彦超团队和山西医科大学王效春团队仔细研究[1]了这些人的大脑：他们的视觉皮层功能完好，视觉本身并未受损； 真正“断线”的，其实是视觉皮层与大脑中语言相关区域之间的联系。 可这就更让人困惑了。语言出了问题，为何会影响对视觉的理解…"
