    "description": "新华社德黑兰8月9日电（记者陈霄 沙达提）据多家伊朗媒体9日报道，伊朗总统佩泽希齐扬与伊朗最高领袖穆杰塔巴·哈梅内伊会面，就伊朗经济和军事等问题交换了意见。 报道说，双方在会见中详细讨论了伊朗当前面临的问题和困难，重点涉及保障民众生活需求、当前“第三场强加战争”形势及未来发展、军事领域动态，以及外汇和能源等方面的保障和支出管理问题。双方还就同外国有关方面开展经济互动交换了意见。",
    "content": "新华社德黑兰8月9日电（记者陈霄 沙达提）据多家伊朗媒体9日报道，伊朗总统佩泽希齐扬与伊朗最高领袖穆杰塔巴·哈梅内伊会面，就伊朗经济和军事等问题交换了意见。 报道说，双方在会见中详细讨论了伊朗当前面临的问题和困难，重点涉及保障民众生活需求、当前“第三场强加战争”形势及未来发展、军事领域动态，以及外汇和能源等方面的保障和支出管理问题。双方还就同外国有关方面开展经济互动交换了意见。"
