    "title": "多方力量闻“风”而动严阵以待筑牢安全防线 全力保障人民群众生命财产安全",
    "link": "https://www.chinanews.com.cn/gn/2026/08-09/10674781.shtml",
    "pub_date": "2026-08-09 19:40:44",
    "author": "",
    "description": "央视网消息：8月9日早上6点，今年第13号台风“白海豚”的中心位于浙江温州市偏东方向约290公里的东海南部海面上，就是北纬27.5度、东经123.6度，中心附近最大风力有14级，强度等级为强台风级。预计，“白海豚”将以每小时15—20公里的速度向西偏北方向移动，强度维持或略有减弱，将于9日晚上至10日早晨在浙江舟山到福建福鼎一带沿海登陆，登陆后继续向西偏北方向移动，强度逐渐减弱。中央气象台9日早6点继续发布台风橙色预警。",
